--   UPDATE `creature_template` SET `unit_flags` = 16793600 WHERE `entry` = 34840;

DELETE FROM `npc_spellclick_spells` WHERE `npc_entry` = 34840;

UPDATE `creature_template` SET `unit_flags` = 32768 WHERE `entry` = 34840;
