--   UPDATE creature_template_difficulty SET DamageModifier=13   WHERE difficulty='DUNGEON_HEROIC' AND id IN (43614,44577,44819,44896,44922,44924,44926,44932,44976,44977,44980,44981,44982,45062,45097,45122);
